import random

class Jackpot:
    def __init__(self):
        self.balloons = ['red', 'blue', 'green', 'yellow']

    def draw(self):
        return random.choice(self.balloons)

    def cheat(self):
        return 'green'

jackpot = Jackpot()

balance = 0
while True:
    draw = input("Press Enter to draw a balloon...")

    if draw == "":
        color = jackpot.draw()
    else:
        color = jackpot.cheat()

    if color == 'red':
        print("Congratulations! You won $1 million!")
        balance += 1000000
        print(f"New balance: ${balance}")
    else:
        print(f"Sorry, you got a {color} balloon.")
    draw = input("Would you like to play again? (y/n)")
    if draw == 'n':
        break

